# The evidence ladder ranked by accuracy, per tissue (1.1.0).
#
# CPGD_RUNG_ACCURACY (R/rung_accuracy_table.R, generated by
# tools/validate_rung_accuracy.R) scores every evidence source in each target
# tissue against a measured yardstick independent of that source: MESA sorted
# blood cells for adult blood, HELIX pairs outside the catalogue's training set
# for child blood, EVA-PR nasal for nasal epithelium, FUSION and GTEx solid
# tissue (each held out in turn) for solid tissue. From it:
#
#   the ORDER of the ladder in a tissue: sources by the lower bound of the
#     95% interval of the figure they carry there (below), highest first --
#     the number a call returns by default, so the source that answers always
#     carries the highest weight available, and a small sample cannot outrank
#     a large one on a noisy point. Nothing else enters (no tier, stratum or
#     parent placement); ties go to the higher point estimate, then the order
#     of CPGD_LADDER_SOURCES. A source whose point estimate is below 0.5 in
#     the tissue, or that has no figure (no validation pair in any yardstick),
#     never supplies a sign there.
#   the FIGURE a call carries: the source's own agreement and Wilson interval
#     in the tissue when it has >= 30 yardstick pairs there, else its
#     cross-tissue figure (all yardsticks pooled, at any n: the interval
#     carries the sample size). Child blood uses the HELIX
#     figure where HELIX scores the source on >= 100 pairs, the adult (MESA)
#     figure otherwise. Age never changes the order (it is the adult figure's
#     order in blood).
#
# Everything here is computed from the table at run time; nothing is written by
# hand except the descriptions.

CPGD_CHILD_MIN_N <- 100L
CPGD_FIGURE_MIN_N <- 30L

CPGD_RUNG_TARGETS <- c(blood = "blood", nasal_epithelium = "nasal epithelium",
                       solid_tissue = "solid tissue")

# The sources the CpG and pair ladders choose among.
CPGD_LADDER_SOURCES <- c(
  paste0("measured_", rep(c("blood", "nasal", "solid"), each = 2),
         c("_replicated", "_single")),
  paste0("smr_", c("replicated_S1", "replicated_S2", "high", "moderate",
                   "moderate_finngen", "moderate_s3_replicated",
                   "moderate_discordant_celltype", "weak", "weak_discordant")),
  "catalogue_consensus_A", "catalogue_consensus_B",
  paste0("catalogue_single_", rep(c("blood", "nasal", "solid"), each = 2), c("_A", "_B")),
  "onco_consensus", "distance_only")

CPGD_RUNG_DESC <- c(
  measured_blood_replicated = "measured in blood, 2+ independent cohorts agree",
  measured_blood_single     = "measured in blood, one study",
  measured_nasal_replicated = "measured in nasal epithelium, 2+ independent cohorts agree",
  measured_nasal_single     = "measured in nasal epithelium, one study",
  measured_solid_replicated = "measured in solid tissue, 2+ independent cohorts agree",
  measured_solid_single     = "measured in solid tissue, one study",
  smr_replicated_S1 = "SMR tier S1, same sign in eQTLGen and FinnGen PBMC",
  smr_replicated_S2 = "SMR tier S2, same sign in eQTLGen and FinnGen PBMC",
  smr_high          = "SMR tier S1, concordant instruments",
  smr_moderate      = "SMR tier S2, single instrument",
  smr_moderate_finngen = "SMR p<5e-8 at the top cis-mQTL, FinnGen PBMC outcome only",
  smr_moderate_s3_replicated = "SMR tier S3, majority sign reproduced by FinnGen PBMC",
  smr_moderate_discordant_celltype = "SMR tier S2, FinnGen cell-type arm disagrees",
  smr_weak          = "SMR tier S3, instruments disagree",
  smr_weak_discordant = "SMR tier S1, FinnGen PBMC disagrees, eQTLGen sign kept",
  catalogue_consensus_A = "catalogue models agree, tier A",
  catalogue_consensus_B = "catalogue models agree, tier B",
  catalogue_single_blood_A = "blood catalogue model alone, tier A",
  catalogue_single_blood_B = "blood catalogue model alone, tier B",
  catalogue_single_nasal_A = "nasal catalogue model alone, tier A",
  catalogue_single_nasal_B = "nasal catalogue model alone, tier B",
  catalogue_single_solid_A = "solid-tissue catalogue model alone, tier A",
  catalogue_single_solid_B = "solid-tissue catalogue model alone, tier B",
  catalogue_model_blood_A = "blood catalogue model, tier A",
  catalogue_model_blood_B = "blood catalogue model, tier B",
  catalogue_model_nasal_A = "nasal catalogue model, tier A",
  catalogue_model_nasal_B = "nasal catalogue model, tier B",
  catalogue_model_solid_A = "solid-tissue catalogue model, tier A",
  catalogue_model_solid_B = "solid-tissue catalogue model, tier B",
  onco_consensus = "Onco-eQTM O1, 5+ cancer types agree",
  distance_only  = "the three distance curves agree",
  distance_curve_blood = "blood distance curve",
  distance_curve_nasal = "nasal distance curve",
  distance_curve_solid = "solid-tissue distance curve")

.cpgd_rung_target <- function(target) {
  if (is.null(target) || is.na(target)) "blood" else match.arg(target, CPGD_TISSUES)
}

.cpgd_wilson <- function(k, n, z = stats::qnorm(0.975)) {
  p <- k / n; d <- 1 + z^2 / n
  c0 <- (p + z^2 / (2 * n)) / d
  h <- z * sqrt(p * (1 - p) / n + z^2 / (4 * n^2)) / d
  c(agree = p, lo = max(0, c0 - h), hi = min(1, c0 + h))
}

# The figure one source carries in one tissue and age: list(agree, lo, hi, n,
# yardstick, basis, population). NULL where the source is unscored.
.cpgd_rung_figure1 <- function(source, target = "blood", age = "adult") {
  target <- .cpgd_rung_target(target)
  R <- CPGD_RUNG_ACCURACY
  pick <- function(t, a) {
    i <- which(R$source == source & R$target == t & R$age == a)
    if (length(i)) R[i[1], ] else NULL
  }
  row <- NULL; pop <- CPGD_RUNG_TARGETS[[target]]
  if (identical(target, "blood")) {
    if (identical(age, "child")) {
      ch <- pick("blood", "child")
      if (!is.null(ch) && ch$n >= CPGD_CHILD_MIN_N) { row <- ch; pop <- "child blood" }
    }
    if (is.null(row)) { row <- pick("blood", "adult"); pop <- "adult blood" }
  } else {
    row <- pick(target, "any")
  }
  if (!is.null(row) && row$n >= CPGD_FIGURE_MIN_N) {
    return(list(agree = row$agree, lo = row$lo, hi = row$hi, n = row$n,
                yardstick = row$yardstick, basis = "own", population = pop))
  }
  # the cross-tissue figure at any n: its Wilson interval carries the sample
  # size, and the lower bound a call returns is floored at 0.5
  all <- R[R$source == source, ]
  if (!nrow(all) || sum(all$n) < 1) return(NULL)
  w <- .cpgd_wilson(sum(all$k), sum(all$n))
  list(agree = round(unname(w[["agree"]]), 4), lo = round(unname(w[["lo"]]), 4),
       hi = round(unname(w[["hi"]]), 4), n = sum(all$n),
       n_here = if (is.null(row)) 0L else row$n, yardstick = "all yardsticks",
       basis = "cross-tissue", population = pop)
}

# The quoted text for a figure.
.cpgd_rung_text <- function(source, f) {
  if (is.null(f)) {
    # a known source that no yardstick scores: said so, with the neutral
    # weight 0.5 (a sign, but no evidence it beats chance)
    if (source %in% names(CPGD_RUNG_DESC))
      return(sprintf("unquantified (%s: no independent validation pair; neutral weight 0.5)",
                     CPGD_RUNG_DESC[[source]]))
    return(NA_character_)
  }
  base <- sprintf("%.2f [%.2f, %.2f] in %s: %s", f$agree, f$lo, f$hi, f$population,
                  CPGD_RUNG_DESC[[source]])
  if (identical(f$basis, "own")) {
    sprintf("%s (vs %s, n=%s)", base, f$yardstick, format(f$n, big.mark = ","))
  } else {
    sprintf("%s (cross-tissue figure, n=%s; %s pair(s) in %s)", base,
            format(f$n, big.mark = ","), f$n_here, f$population)
  }
}

# Vectorised label: one string per (source, target, age). age "any" joins the
# adult and the child text with " | " where they differ (blood only).
.cpgd_rung_label <- function(source, target = "blood", age = "adult") {
  target <- .cpgd_rung_target(target)
  out <- rep(NA_character_, length(source))
  ok <- which(!is.na(source))
  if (!length(ok)) return(out)
  u <- unique(source[ok])
  one <- function(s, a) .cpgd_rung_text(s, .cpgd_rung_figure1(s, target, a))
  lab <- vapply(u, function(s) {
    if (identical(age, "any")) {
      a <- one(s, "adult"); k <- one(s, "child")
      if (is.na(a) || identical(a, k)) a else if (is.na(k)) a else paste0(a, " | ", k)
    } else one(s, age)
  }, character(1), USE.NAMES = FALSE)
  out[ok] <- lab[match(source[ok], u)]
  out
}

# The ladder order in one tissue: sources (of `pool`) by the lower bound of
# their figure there, highest first, without those whose point estimate is
# below 0.5. Age never changes it.
.cpgd_rung_order <- function(target = "blood", pool = CPGD_LADDER_SOURCES) {
  target <- .cpgd_rung_target(target)
  age <- if (identical(target, "blood")) "adult" else "any"
  F <- lapply(pool, function(s) .cpgd_rung_figure1(s, target, age))
  pt <- vapply(F, function(f) if (is.null(f)) NA_real_ else f$agree, numeric(1))
  lo <- vapply(F, function(f) if (is.null(f)) NA_real_ else f$lo, numeric(1))
  keep <- !is.na(pt) & pt >= 0.5
  pool[keep][order(-lo[keep], -pt[keep], seq_along(pool)[keep])]
}

# Apply a ladder. `cand` is a named list of sign vectors (NA = no call), one per
# source; `ord` the order; `conflict` marks rows whose catalogue models
# disagree: from the distance rung down, those rows abstain as
# tissue_conflict rather than let a weaker source settle the disagreement.
# Returns list(best, key) where key is the fine source or a state.
.cpgd_apply_ladder <- function(cand, ord, conflict, n) {
  best <- rep(NA_real_, n); key <- rep(NA_character_, n)
  conflict[is.na(conflict)] <- FALSE
  for (s in ord) {
    if (identical(s, "distance_only")) {
      i <- which(is.na(key) & conflict)
      key[i] <- "tissue_conflict"
    }
    v <- cand[[s]]
    if (is.null(v)) next
    i <- which(is.na(key) & !is.na(v))
    best[i] <- v[i]; key[i] <- s
  }
  i <- which(is.na(key) & conflict)
  key[i] <- "tissue_conflict"
  list(best = best, key = key)
}

# The catalogue candidates of both ladders, from the per-tissue calls. D, TT,
# ST: n x 3 matrices (blood, nasal, solid) of call signs (NA = no call), tiers
# and statuses; G: the gene each tissue's model named (NULL: one gene per row,
# as in a pair). A DIRECT_eQTM call is one study's measured sign, not a
# prediction: it comes back in `direct`, for the measured rung of its tissue,
# and takes no part in a consensus. A consensus needs 2+ (and min_tissues)
# predicted calls naming the same gene, all agreeing; predicted calls naming
# different genes are each a single call about their own gene; a conflict is
# 2+ predicted calls on the same gene that disagree.
.cpgd_catalogue_cand <- function(D, TT, ST, G = NULL, min_tissues = 2L) {
  n <- nrow(D)
  isdir <- !is.na(D) & !is.na(ST) & ST == "DIRECT_eQTM"
  P <- D; P[isdir] <- NA
  direct <- D; direct[!isdir] <- NA
  nc <- rowSums(!is.na(P))
  same <- rep(TRUE, n)
  if (!is.null(G)) {
    Gn <- toupper(gsub("_", "-", G))
    same <- vapply(seq_len(n), function(i) {
      g <- Gn[i, !is.na(P[i, ])]
      length(unique(g[!is.na(g)])) <= 1L
    }, logical(1))
  }
  npos <- rowSums(P == 1, na.rm = TRUE)
  nneg <- rowSums(P == -1, na.rm = TRUE)
  worst <- vapply(seq_len(n), function(i) {
    v <- TT[i, !is.na(P[i, ])]; v <- v[!is.na(v)]
    if (length(v)) max(v) else NA_character_
  }, character(1))
  cons <- ifelse(nc >= max(2L, min_tissues) & same & (npos == nc | nneg == nc),
                 ifelse(npos > 0, 1, -1), NA_real_)
  conflict <- nc >= 2L & same & npos > 0 & nneg > 0
  single <- P
  single[!(nc == 1L | !same), ] <- NA
  list(cons = cons, worst = worst, single = single, conflict = conflict, direct = direct)
}

# Fine source -> the coarse best_evidence label the outputs keep.
.cpgd_rung_evidence <- function(key) {
  data.table::fcase(
    startsWith(key, "measured_"), "measured",
    startsWith(key, "smr_replicated"), "smr_replicated",
    key %in% "smr_high", "smr_high",
    startsWith(key, "smr_moderate"), "smr_moderate",
    startsWith(key, "smr_weak"), "smr_weak",
    startsWith(key, "catalogue_consensus"), "catalogue_consensus",
    startsWith(key, "catalogue_single"), "catalogue_single",
    default = key)
}

# The donor group of a measured cohort. Subsets of one study (EVA-PR's asthma
# and control strata, MESA's monocytes and T cells, GTEx's tissues) share
# donors, so a sign they agree on is one study's result, not a replication.
.cpgd_donor_group <- function(cohort) {
  cohort <- trimws(as.character(cohort))
  data.table::fcase(
    startsWith(cohort, "GTEx"), "GTEx",
    startsWith(cohort, "EVA-PR"), "EVAPR",
    grepl("Framingham", cohort, fixed = TRUE), "FHS",
    startsWith(cohort, "HELIX"), "HELIX",
    startsWith(cohort, "MESA"), "MESA",
    startsWith(cohort, "ROSMAP"), "ROSMAP",
    default = cohort)
}

# Measured signs per tissue for (cpg_id, gene) queries: list(blood, nasal,
# solid), each list(d, rep) aligned with cpg_id. `g1` is tried first, then
# `g2`; `norm` normalises gene spellings on both sides. rep = 2+ independent
# donor groups (.cpgd_donor_group) measured the pair in that tissue and >= 0.99
# of the cohorts agree. A table without a `cohorts` column falls back to
# `n_cohorts`.
.cpgd_measured_by_tissue <- function(M, cpg_id, g1, g2 = NULL, norm = toupper) {
  n <- length(cpg_id)
  short <- c(blood = "blood", nasal_epithelium = "nasal", solid_tissue = "solid")
  empty <- list(d = rep(NA_real_, n), rep = rep(NA, n))
  res <- setNames(rep(list(empty), 3L), unname(short))
  if (is.null(M) || !nrow(M)) return(res)
  # only the queried CpGs can match; the rest of the table is never read
  M <- M[which(as.character(M$cpg_id) %in% as.character(cpg_id)), ]
  if (!nrow(M)) return(res)
  # a measured table without a tissue column is read as blood
  nco <- if ("n_cohorts" %in% names(M)) suppressWarnings(as.integer(M$n_cohorts)) else rep(1L, nrow(M))
  agr <- if ("cohort_agreement" %in% names(M)) suppressWarnings(as.numeric(M$cohort_agreement)) else rep(1, nrow(M))
  X <- data.table::data.table(i = seq_len(nrow(M)),
                              cpg_id = as.character(M$cpg_id), g = norm(M$target_gene),
                              tis = if ("tissue" %in% names(M)) as.character(M$tissue) else "blood",
                              d = sign(as.numeric(M$direction)),
                              nco = ifelse(is.na(nco), 1L, nco), agr = ifelse(is.na(agr), 1, agr))
  X <- X[!is.na(X$d) & X$tis %in% names(short)]
  # independent donor groups per pair and tissue
  if ("cohorts" %in% names(M)) {
    co <- strsplit(as.character(M$cohorts)[X$i], "|", fixed = TRUE)
    ri <- rep(seq_along(co), lengths(co))      # row of X for each cohort name
    ug <- .cpgd_donor_group(unlist(co))
    ok <- !is.na(ug) & nzchar(ug)
    ri <- ri[ok]; ug <- ug[ok]
    # a row without cohort names is one group of its own
    j <- setdiff(seq_len(nrow(X)), ri)
    if (length(j)) { ri <- c(ri, j); ug <- c(ug, paste0(".row", X$i[j])) }
    stopifnot(length(ri) == length(ug))
    G <- data.table::data.table(tis = X$tis[ri], cpg_id = X$cpg_id[ri], g = X$g[ri], grp = ug)
    G <- unique(G)[, list(ngrp = .N), by = c("tis", "cpg_id", "g")]
  } else {
    G <- NULL
  }
  # per pair and tissue: the sign if every record agrees, else NA; cohorts
  # summed; the lowest agreement. Grouped without get() in j, which data.table
  # cannot optimise and which exhausted memory on the full measured table.
  keys <- c("tis", "cpg_id", "g")
  lo <- X[, lapply(.SD, min), by = keys, .SDcols = c("d", "agr")]
  hi <- X[, lapply(.SD, max), by = keys, .SDcols = "d"]
  sm <- X[, lapply(.SD, sum), by = keys, .SDcols = "nco"]
  X <- data.table::data.table(lo[, keys, with = FALSE],
                              d = ifelse(lo$d == hi$d, lo$d, NA_real_),
                              nco = sm$nco, agr = lo$agr)
  if (!is.null(G)) {
    X <- merge(X, G, by = c("tis", "cpg_id", "g"), all.x = TRUE)
    data.table::set(X, j = "nco", value = ifelse(is.na(X$ngrp), X$nco, X$ngrp))
    X[, "ngrp" := NULL]
  }
  # queries are built outside `[`, where cpg_id and g would resolve to X's own
  # columns (the data.table scoping trap)
  q1 <- data.table::data.table(cpg_id = as.character(cpg_id), g = g1)
  q2 <- if (is.null(g2)) NULL else data.table::data.table(cpg_id = as.character(cpg_id), g = g2)
  for (tname in names(short)) {
    Xt <- X[X$tis == tname]
    if (!nrow(Xt)) next
    data.table::setkeyv(Xt, c("cpg_id", "g"))
    h1 <- Xt[q1, on = c("cpg_id", "g")]
    d <- h1$d; nc <- h1$nco; ag <- h1$agr
    if (!is.null(q2)) {
      h2 <- Xt[q2, on = c("cpg_id", "g")]
      j <- is.na(d) & !is.na(h2$d)
      d[j] <- h2$d[j]; nc[j] <- h2$nco[j]; ag[j] <- h2$agr[j]
    }
    res[[short[[tname]]]] <- list(d = d, rep = !is.na(d) & nc >= 2L & ag >= 0.99)
  }
  res
}
